<?php
/** Kiểm tra vị trí tiết dùng chung cho chỉnh tay và đề xuất AI. */
function ttb_manual_slot_error(array$data,array$entry,int$day,string$session,int$period):string{$slot=['day'=>$day,'session'=>$session,'period'=>$period,'key'=>ttb_slot_key($day,$session,$period)];if(ttb_slot_unavailable($data,$entry,$slot))return'Giáo viên hoặc lớp bận/không học tại vị trí này.';if(!empty($entry['fixed_day'])&&($day!==(int)$entry['fixed_day']||(!empty($entry['fixed_session'])&&$session!==(string)$entry['fixed_session'])||(!empty($entry['fixed_period'])&&$period!==(int)$entry['fixed_period'])))return'Tiết cố định không thể chuyển khỏi vị trí đã khai báo.';if(!empty($entry['allowed_session'])&&$session!==(string)$entry['allowed_session'])return'Môn học không được xếp vào buổi này.';if(!empty($entry['allowed_period_from'])&&$period<(int)$entry['allowed_period_from'])return'Tiết nằm trước khoảng được phép của môn.';if(!empty($entry['allowed_period_to'])&&$period>(int)$entry['allowed_period_to'])return'Tiết nằm sau khoảng được phép của môn.';return'';}
function ttb_transfer_class_matches(string$class,string$scope,string$value):bool{if($scope==='school')return true;if($scope==='class')return$class===$value;return ttb_class_grade($class)===(ltrim($value,'0')?:'0');}
function ttb_transfer_entry_matches(array$entry,string$scope,string$value):bool{foreach((array)($entry['classes']??[])as$class)if(ttb_transfer_class_matches((string)$class,$scope,$value))return true;return false;}
function ttb_transfer_entry_fully_matches(array$entry,string$scope,string$value):bool{$classes=(array)($entry['classes']??[]);if(!$classes)return false;foreach($classes as$class)if(!ttb_transfer_class_matches((string)$class,$scope,$value))return false;return true;}
